from pathlib import Path
terms=('right flag','backward coherence','forward coherence','conservation')
for p in Path('research/aspect').rglob('*'):
 if p.is_file() and p.suffix in {'.md','.json','.py','.toml'}:
  try: lines=p.read_text(encoding='utf-8').splitlines()
  except: continue
  for i,s in enumerate(lines,1):
   if any(t in s.lower() for t in terms): print(f'{p}:{i}:{s[:300]}')
